import { Access, usePermissions } from '../auth/AuthContext';
import { useListPosition, useViewState } from '../hooks/useWorkspaceView';
import { formatDuration } from '../lib/display';
import { PageHeading } from '../components/PageHeading';
import { WorkspacePanels } from '../components/WorkspacePanels';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '../components/ui/tabs';
import { Choice } from '../components/Choice';
import { usePageDirty } from '../hooks/usePageDirty';
import { confirmAction } from '../lib/confirmation';
import { useCallback, useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { Archive, ArrowDownToLine, ArrowLeft, ArrowRight, AudioLines, Check, CheckCircle2, ChevronLeft, ChevronRight, CircleAlert, Clock3, FilePenLine, FileText, Headphones, History, Layers3, LoaderCircle, LockKeyhole, Mic, Play, Plus, Search, Settings2, ShieldCheck, Sparkles, Square, Upload, UserRound, X } from 'lucide-react';
import { api } from '../api';
import { Dialog } from '../components/Dialog';
import { useRecorder } from '../hooks/useRecorder';
import type { PageId } from '../navigation';
import type { Person } from '../people-types';
import type { AudioClip, RecordCapabilities, RecordDetail, RecordList, RecordMeta, RecordScenario, RecordStatus, Segment, SegmentInput, Speaker } from '../record-types';
import { recordError, recordStatusLabels, recordTime, scenarioLabels, speakerLabels } from '../record-types';

type EditorSegment = SegmentInput & { key: string };
type PendingFile = { file: File; url: string };
type StudioTab = 'audio' | 'original' | 'edit' | 'analysis' | 'preview';
const metaOf = (record: RecordDetail): RecordMeta => ({ title: record.title, scenario: record.scenario, location: record.location, interviewers: record.interviewers, occurred_at: record.occurred_at });
const segmentFields = (segment: SegmentInput): SegmentInput => ({ ...(segment.id ? { id: segment.id } : {}), audio_id: segment.audio_id, start_ms: segment.start_ms, end_ms: segment.end_ms, speaker: segment.speaker, text: segment.text });
const editSegments = (segments: Segment[]): EditorSegment[] => segments.map(segment => ({ ...segmentFields(segment), key: segment.id }));
const dateInput = (value: string | null) => value ? new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date(value)).replace(' ', 'T') : '';
const durationText = (seconds: number) => `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(Math.floor(seconds % 60)).padStart(2, '0')}`;
const bytesText = (bytes: number) => bytes >= 1024 * 1024 ? `${(bytes / (1024 * 1024)).toFixed(1)} MiB` : `${(bytes / 1024).toFixed(1)} KiB`;
const providerName = (value?: string) => value === 'local' ? '历史文字整理' : value === 'deepseek' ? 'DeepSeek' : '硅基流动';
function Notice({ error, message }: { error?: string; message?: string }) { return <>{error && <div className="rec-notice error" role="alert"><CircleAlert size={17}/><span>{error}</span></div>}{message && <div className="rec-notice success" role="status"><CheckCircle2 size={17}/><span>{message}</span></div>}</>; }
function Empty({ icon, title, children }: { icon: ReactNode; title: string; children: ReactNode }) { return <div className="rec-empty"><span>{icon}</span><h3>{title}</h3><p>{children}</p></div>; }

function CreateRecord({ onClose, onCreated }: { onClose: () => void; onCreated: (id: string) => void }) {
  const [form, setForm] = useState<RecordMeta>({ title: '', scenario: 'other', location: '', interviewers: '', occurred_at: null });
  const [query, setQuery] = useState(''), [people, setPeople] = useState<Person[]>([]), [selected, setSelected] = useState<Person | null>(null);
  const [searching, setSearching] = useState(false), [searched, setSearched] = useState(false), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const dirty = Boolean(form.title || form.location || form.interviewers || form.occurred_at || form.scenario !== 'other' || selected || query);
  usePageDirty(dirty || busy);
  const close = async () => { if (!busy && (!dirty || (await confirmAction('笔录尚未创建，确定放弃本次填写吗？', {"title":"保留这次修改？","confirmLabel":"放弃修改","cancelLabel":"继续编辑","tone":"warning"})))) onClose(); };
  async function findPeople() { setSearching(true); setSearched(true); setError(''); try { const result = await api<{ items: Person[] }>(`/people?${new URLSearchParams({ q: query.trim(), archived: 'false', page_size: '20' })}`); if (!Array.isArray(result?.items)) throw new Error('人员查询响应不完整。'); setPeople(result.items); } catch (error) { setError(recordError(error)); } finally { setSearching(false); } }
  async function create(event: FormEvent) { event.preventDefault(); if (busy || !form.title.trim()) return; setBusy(true); setError(''); try { const result = await api<RecordDetail>('/records', { method: 'POST', body: JSON.stringify({ ...form, person_id: selected?.id || null }) }); if (!result?.id) throw new Error('创建响应不完整，请刷新笔录库确认。'); onCreated(result.id); } catch (error) { setError(recordError(error)); } finally { setBusy(false); } }
  return <Dialog title="创建询问笔录" onClose={close} className="rec-create-dialog"><form onSubmit={create}><div className="rec-dialog-lead"><span><AudioLines size={25}/></span><div><h3>从真实的声音开始。</h3><p>原音、原始转写与人工修订分别留存，随时回到依据。</p></div></div><div className="rec-form-grid"><label className="field rec-wide"><span>笔录标题 *</span><input className="input" value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} maxLength={200} required disabled={busy} placeholder="为本次询问填写一个清晰的标题"/></label><label className="field"><span>业务场景</span><Choice className="select" value={form.scenario} onChange={event => setForm({ ...form, scenario: event.target.value as RecordScenario })} disabled={busy}>{Object.entries(scenarioLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Choice></label><label className="field"><span>询问地点</span><input className="input" maxLength={500} value={form.location} onChange={event => setForm({ ...form, location: event.target.value })} disabled={busy}/></label><label className="field rec-wide"><span>询问人员</span><input className="input" maxLength={500} value={form.interviewers} onChange={event => setForm({ ...form, interviewers: event.target.value })} disabled={busy}/></label><label className="field rec-wide"><span>询问发生时间（北京时间，可留空）</span><input className="input" type="datetime-local" value={dateInput(form.occurred_at)} onChange={event => setForm({ ...form, occurred_at: event.target.value ? `${event.target.value}:00+08:00` : null })} disabled={busy}/><small className="rec-muted">按实际询问时间填写；不使用创建时间代替。</small></label></div>
    <div className="rec-person-picker"><label className="field"><span>关联人员档案（可选）</span><div className="rec-search"><Search size={16}/><input value={query} maxLength={200} onChange={event => setQuery(event.target.value)} placeholder="搜索姓名、证件号码或国籍" onKeyDown={event => { if (event.key === 'Enter') { event.preventDefault(); if (!busy && !searching) void findPeople(); } }} disabled={busy || searching}/><button type="button" disabled={busy || searching} onClick={findPeople}>{searching ? '查询中' : '查找'}</button></div></label>{selected && <div className="rec-person-selected"><UserRound size={18}/><strong>{selected.name}</strong><span>{selected.code}</span><button type="button" className="icon-button" onClick={() => setSelected(null)} disabled={busy} aria-label="取消关联人员"><X size={15}/></button></div>}{!!people.length && <div className="rec-person-options">{people.map(person => <button type="button" key={person.id} disabled={busy} onClick={() => { setSelected(person); setPeople([]); }}><UserRound size={16}/><span><strong>{person.name}</strong><small>{person.code} · {person.nationality}</small></span><Plus size={14}/></button>)}</div>}{searched && !searching && !people.length && !selected && <p className="rec-muted">未找到匹配人员；可以不关联档案继续创建。</p>}</div>
    <div className="rec-boundary"><LockKeyhole size={16}/><p>创建与录音保存均在本地完成。只有明确确认转写或摘要时，才发送对应内容至服务商。</p></div><Notice error={error}/><div className="rec-form-footer"><span>根据场景匹配本地笔录模板</span><button type="button" className="btn btn-secondary" onClick={close} disabled={busy}>取消</button><button className="btn btn-primary" disabled={busy || !form.title.trim()}>{busy ? <LoaderCircle className="spinning" size={16}/> : <ArrowRight size={16}/>}进入录音工作室</button></div></form></Dialog>;
}

function Studio({ id, capabilities, onBack, onChanged, onNavigate, onReloadCapabilities }: { id: string; capabilities: RecordCapabilities | null; onBack: () => void; onChanged: () => void; onNavigate: (page: PageId) => void; onReloadCapabilities: () => void }) {
  const [record, setRecord] = useState<RecordDetail | null>(null);
  const [meta, setMeta] = useState<RecordMeta>({ title: '', scenario: 'other', location: '', interviewers: '', occurred_at: null });
  const [segments, setSegments] = useState<EditorSegment[]>([]);
  const [tab, setTab] = useState<StudioTab>('audio');
  const [loading, setLoading] = useState(true), [busy, setBusy] = useState(''), [error, setError] = useState(''), [notice, setNotice] = useState('');
  const [file, setFile] = useState<PendingFile | null>(null);
  const [fileDuration, setFileDuration] = useState('');
  const [activeAudio, setActiveAudio] = useState('');
  const [dialog, setDialog] = useState<{ type: 'asr'; clip: AudioClip } | { type: 'analysis' | 'review' } | null>(null);
  const [confirmed, setConfirmed] = useState(false), [reviewNote, setReviewNote] = useState(''), [includeAI, setIncludeAI] = useState(false);
  const [snapshot, setSnapshot] = useState<{ title: string; text: string; note?: string } | null>(null);
  const audio = useRef<HTMLAudioElement>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  const pendingSeek = useRef<number | null>(null);
  const segmentCounter = useRef(0);
  const recorder = useRecorder();
  const apply = useCallback((value: RecordDetail) => { if (!value?.id || !Array.isArray(value.audio_clips) || !Array.isArray(value.segments)) throw new Error('笔录详情响应不完整。'); setRecord(value); setMeta(metaOf(value)); setSegments(editSegments(value.segments)); setReviewNote(value.review_note || ''); setConfirmed(false); }, []);
  const load = useCallback(async () => { setLoading(true); setError(''); try { apply(await api<RecordDetail>(`/records/${id}`)); } catch (error) { setError(recordError(error)); } finally { setLoading(false); } }, [id, apply]);
  useEffect(() => { window.scrollTo({ top: 0, behavior: 'instant' }); }, []);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => () => { if (file) URL.revokeObjectURL(file.url); }, [file]);
  useEffect(() => { if (!record?.analysis || record.analysis.stale || record.analysis.provider === 'local') setIncludeAI(false); }, [record?.analysis]);
  const metaDirty = Boolean(record && JSON.stringify(meta) !== JSON.stringify(metaOf(record)));
  const segmentsDirty = Boolean(record && JSON.stringify(segments.map(segmentFields)) !== JSON.stringify(record.segments.map(segmentFields)));
  const textDirty = metaDirty || segmentsDirty;
  const pendingLocal = recorder.local || file;
  const captureBusy = recorder.recording || recorder.starting || recorder.stopping;
  const reviewDirty = Boolean(dialog?.type === 'review' && reviewNote !== (record?.review_note || ''));
  usePageDirty(textDirty || Boolean(pendingLocal) || captureBusy || Boolean(busy) || reviewDirty);
  const { write } = usePermissions();
  const locked = !write || record?.status !== 'draft';
  const maxAudio = capabilities?.limits.max_audio_bytes || 20 * 1024 * 1024;
  const maxClips = capabilities?.limits.max_clips || 30;
  const totalAudioBytes = record?.audio_clips.reduce((sum, clip) => sum + clip.size_bytes, 0) || 0;
  const maxTotalAudio = capabilities?.limits.max_record_audio_bytes || 500 * 1024 * 1024;
  const totalChars = segments.reduce((sum, segment) => sum + segment.text.length, 0);
  const chosenAudio = record?.audio_clips.find(clip => clip.id === activeAudio);
  const localBlob = recorder.local?.blob || file?.file;
  const localURL = recorder.local?.url || file?.url;
  const localName = recorder.local?.filename || file?.file.name;
  const canMutate = !busy && !captureBusy && !locked;
  const readyForAction = canMutate && !textDirty && !pendingLocal;
  const back = async () => { if (busy || recorder.starting || recorder.stopping) return; if ((textDirty || pendingLocal || captureBusy || reviewDirty) && !(await confirmAction('仍有未保存内容或录音，离开会丢失本地内容。确定返回笔录库吗？', {"title":"保留这次修改？","confirmLabel":"放弃修改","cancelLabel":"继续编辑","tone":"warning"}))) return; onBack(); };
  const audioLibraryAvailable = Boolean(capabilities?.ai.audio_library_available);
  const openDialog = (next: NonNullable<typeof dialog>) => { setConfirmed(false); setError(''); setDialog(next); };
  const closeDialog = async () => { if (busy) return; if (reviewDirty && !(await confirmAction('核对意见尚未提交，确定放弃本次填写吗？', {"title":"保留这次修改？","confirmLabel":"放弃修改","cancelLabel":"继续编辑","tone":"warning"}))) return; setReviewNote(record?.review_note || ''); setDialog(null); setConfirmed(false); };
  const discardLocal = async () => { if (!(await confirmAction('确定丢弃这段尚未保存的本地音频吗？', {"title":"丢弃这段录音？","confirmLabel":"丢弃录音","cancelLabel":"保留录音","tone":"danger"}))) return; recorder.discard(); setFile(null); setFileDuration(''); if (fileInput.current) fileInput.current.value = ''; };
  function chooseFile(selected?: File) {
    if (!selected || captureBusy || busy || pendingLocal) return;
    setError(''); setNotice('');
    if (selected.size > maxAudio || !selected.size) { setError(`音频不能为空且不能超过 ${bytesText(maxAudio)}。`); return; }
    if (!(capabilities?.limits.formats || ['wav', 'mp3', 'webm', 'ogg', 'm4a', 'flac']).includes(selected.name.split('.').pop()?.toLowerCase() || '')) { setError('请选择 WAV、MP3、WebM、OGG、M4A 或 FLAC 音频。'); return; }
    setFile({ file: selected, url: URL.createObjectURL(selected) }); setFileDuration('');
  }
  async function saveChanges() {
    if (!record || busy || locked || captureBusy) return;
    if (!meta.title.trim()) { setError('请填写笔录标题。'); return; }
    if (segments.some(segment => !segment.text.trim())) { setError('修订段不能留空，请填写文字或移除空段后保存。'); setTab('edit'); return; }
    if (totalChars > (capabilities?.limits.max_total_text_chars || 100000)) { setError('本份笔录修订文字超过总字数限制，请精简或另建笔录。'); setTab('edit'); return; }
    const invalid = segments.find(segment => (segment.start_ms === null) !== (segment.end_ms === null) || (segment.start_ms !== null && (segment.start_ms < 0 || segment.end_ms! <= segment.start_ms)) || ((segment.start_ms !== null || segment.end_ms !== null) && !segment.audio_id));
    if (invalid) { setError('手工时间需同时填写起止位置、结束大于开始，并关联对应音频。'); setTab('edit'); return; }
    setBusy('save'); setError(''); setNotice('');
    let current = record;
    try {
      if (metaDirty) { current = await api<RecordDetail>(`/records/${id}`, { method: 'PATCH', body: JSON.stringify({ expected_revision: current.revision, ...meta, template_id: meta.scenario }) }); if (!current?.id) throw new Error('资料保存响应不完整，请重新打开确认。'); setRecord(current); setMeta(metaOf(current)); }
      if (segmentsDirty) current = await api<RecordDetail>(`/records/${id}/segments`, { method: 'PATCH', body: JSON.stringify({ expected_revision: current.revision, segments: segments.map(segmentFields) }) });
      apply(current); setNotice('笔录修改已保存，修订历史已留存。'); onChanged();
    } catch (error) { setError(`${recordError(error)} 当前输入仍保留；若提示版本冲突，请先复制未保存文本，再重新打开核对。`); } finally { setBusy(''); }
  }
  async function upload() {
    if (!record || !localBlob || !localName || !canMutate || textDirty) return;
    if (localBlob.size + totalAudioBytes > maxTotalAudio) { setError('此笔录原音总容量将超过 500 MiB。请下载保留本地音频，再另建笔录保存。'); return; }
    if (localBlob.size > maxAudio) { setError('音频超过大小限制，请先下载保留，再拆分成较短音频上传。'); return; }
    setBusy('upload'); setError(''); setNotice('');
    try { const form = new FormData(); form.set('file', localBlob, localName); form.set('expected_revision', String(record.revision)); const duration = recorder.local ? Math.round(recorder.local.duration * 1000) : fileDuration ? Math.round(Number(fileDuration) * 1000) : null; if (duration !== null) { if (!Number.isFinite(duration) || duration <= 0 || duration > (capabilities?.limits.max_duration_ms || 86400000)) throw new Error('声明时长须大于 0，且不超过 24 小时。'); form.set('duration_ms', String(duration)); } const value = await api<RecordDetail>(`/records/${id}/audio`, { method: 'POST', body: form }); apply(value); recorder.discard(); setFile(null); setFileDuration(''); if (fileInput.current) fileInput.current.value = ''; setNotice('原始音频已保存在本地数据库。'); onChanged(); } catch (error) { setError(`${recordError(error)} 本地音频仍保留，可重试或先下载。`); } finally { setBusy(''); }
  }
  async function addLibraryAudio() {
    if (!record || !readyForAction) return;
    setBusy('upload'); setError('');
    try { apply(await api<RecordDetail>(`/records/${id}/audio-library`, { method: 'POST', body: JSON.stringify({ expected_revision: record.revision }) })); setNotice('录音已加入当前笔录，可试听并开始转写。'); onChanged(); }
    catch (error) { setError(recordError(error)); } finally { setBusy(''); }
  }
  async function runAI() {
    if (!record || !dialog || dialog.type === 'review' || !confirmed || busy) return;
    const type = dialog.type; setBusy(type); setError(''); setNotice('');
    try { const path = type === 'asr' ? `/records/${id}/audio/${dialog.clip.id}/transcribe` : `/records/${id}/analyze`; const value = await api<RecordDetail>(path, { method: 'POST', body: JSON.stringify({ expected_revision: record.revision, confirmed: true }) }); apply(value); setDialog(null); setTab(type === 'asr' ? 'original' : 'analysis'); setNotice(type === 'asr' ? '转写已保存；原始转写只读，请在人工修订中核对。' : '摘要与要素已单独保存，请逐条核对引用。'); onChanged(); } catch (error) { const failure = recordError(error); setDialog(null); setConfirmed(false); try { apply(await api<RecordDetail>(`/records/${id}`)); } catch { /* Preserve the last known record if refresh also fails. */ } setError(failure); setTab(type === 'asr' ? 'original' : 'analysis'); } finally { setBusy(''); }
  }
  async function changeStatus(status: 'reviewed' | 'archived') {
    if (!record || busy || textDirty || pendingLocal || captureBusy) return;
    if (status === 'reviewed' && (!confirmed || !reviewNote.trim())) return;
    if (status === 'archived' && !(await confirmAction('归档后笔录只读，确定归档吗？', {"title":"将此记录归档？","confirmLabel":"确认归档","cancelLabel":"暂不归档","tone":"info"}))) return;
    setBusy(status); setError('');
    try { apply(await api<RecordDetail>(`/records/${id}`, { method: 'PATCH', body: JSON.stringify({ expected_revision: record.revision, status, ...(status === 'reviewed' ? { confirmed: true, review_note: reviewNote.trim() } : {}) }) })); setDialog(null); setNotice(status === 'reviewed' ? '已登记人工核对，正文已锁定；仍为未签发稿。' : '笔录已归档。'); onChanged(); } catch (error) { setError(recordError(error)); } finally { setBusy(''); }
  }
  async function restore() {
    if (!record?.archived_from || busy || !(await confirmAction(`恢复到归档前的“${recordStatusLabels[record.archived_from]}”状态？已核对的正文仍保持锁定。`, {"title":"恢复这份笔录？","confirmLabel":"确认恢复","tone":"info"}))) return;
    setBusy('restored'); setError('');
    try { apply(await api<RecordDetail>(`/records/${id}`, { method: 'PATCH', body: JSON.stringify({ expected_revision: record.revision, status: record.archived_from }) })); setNotice('已恢复至归档前状态。'); onChanged(); } catch (error) { setError(recordError(error)); } finally { setBusy(''); }
  }
  async function readRevision(revision: number) {
    setBusy('history'); setError('');
    try { const value = await api<{ revision: number; snapshot: { rendered_text: string } }>(`/records/${id}/revisions/${revision}`); if (typeof value?.snapshot?.rendered_text !== 'string') throw new Error('历史快照响应不完整。'); setSnapshot({ title: `修订版本 v${revision}`, text: value.snapshot.rendered_text, note: '这是该次保存时的成文快照，只读查看，不覆盖当前修订内容。' }); } catch (error) { setError(recordError(error)); } finally { setBusy(''); }
  }
  async function download(format: 'txt' | 'docx') {
    if (!record || busy || textDirty || pendingLocal || captureBusy) return;
    setBusy('export'); setError('');
    try { const response = await fetch(`/api/records/${id}/export.${format}?include_ai=${includeAI}`); if (!response.ok) { const value = await response.json().catch(() => null); throw new Error(typeof value?.detail === 'string' ? value.detail : '导出未完成，请稍后重试。'); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `笔录-${id.slice(0, 8)}.${format}`; anchor.click(); window.setTimeout(() => URL.revokeObjectURL(url), 15000); setNotice('导出文件已生成，请在浏览器下载中查看。'); } catch (error) { setError(recordError(error)); } finally { setBusy(''); }
  }
  function playAudio(clipId: string, seconds = 0) {
    pendingSeek.current = seconds;
    if (activeAudio === clipId && audio.current && audio.current.readyState >= 1) { audio.current.currentTime = seconds; pendingSeek.current = null; void audio.current.play().catch(() => setNotice('请点击播放器播放按钮开始回听。')); }
    else setActiveAudio(clipId);
  }
  function listen(segment: SegmentInput) {
    if (segment.audio_id) playAudio(segment.audio_id, (segment.start_ms || 0) / 1000);
  }
  const changeSegment = (key: string, change: Partial<SegmentInput>) => setSegments(items => items.map(segment => segment.key === key ? { ...segment, ...change } : segment));
  const navigateToSegment = (segmentId: string) => { setTab('edit'); window.setTimeout(() => document.getElementById(`rec-segment-${segmentId}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' }), 60); };
  const busyLabel: Record<string, string> = { history: '正在读取历史快照…', restored: '正在恢复归档…', save: '正在保存修订…', upload: '正在保存原音…', asr: '正在请求硅基流动转写所选音频…', analysis: '正在整理当前已保存文字…', reviewed: '正在保存人工核对…', archived: '正在归档…', export: '正在生成本地文件…' };
  return <div className="page-content records-page rec-studio"><div className="rec-studio-top"><button className="text-button" onClick={back} disabled={Boolean(busy) || recorder.starting || recorder.stopping}><ArrowLeft size={15}/>笔录库</button>{record && <span className={`rec-status ${record.status}`}>{recordStatusLabels[record.status]} · v{record.revision}</span>}</div>
    {loading ? <Empty icon={<LoaderCircle className="spinning" size={28}/>} title="正在打开笔录">读取原始音频、转写及修订历史。</Empty> : !record ? <><Notice error={error}/><button className="btn btn-secondary" onClick={load}>重新读取</button></> : <>
      <header className="page-heading"><div><h1 className="page-title rec-record-title">{record.title}</h1><p className="page-description">{scenarioLabels[record.scenario]} · {record.person_name || '未关联人员档案'} · 更新于 {recordTime(record.updated_at)}</p></div><div className="rec-heading-actions">{record.status === 'draft' && <Access permission="write"><button className="btn btn-primary" onClick={saveChanges} disabled={!textDirty || !canMutate}><Check size={16}/>保存修改</button></Access>}{record.status === 'archived' && record.archived_from && <Access permission="write"><button className="btn btn-secondary" disabled={Boolean(busy)} onClick={restore}><History size={15}/>恢复至{recordStatusLabels[record.archived_from]}</button></Access>}{record.status !== 'archived' && <Access permission="write"><button className="btn btn-secondary" onClick={() => void changeStatus('archived')} disabled={Boolean(busy) || textDirty || Boolean(pendingLocal) || captureBusy}><Archive size={15}/>归档</button></Access>}</div></header>
      <Notice error={error} message={notice}/>{busy && <div className="rec-working" role="status"><LoaderCircle className="spinning" size={17}/>{busyLabel[busy]}</div>}{locked && <div className="rec-boundary"><LockKeyhole size={16}/><p>{record.status === 'reviewed' ? '此笔录已人工核对，原音与正文锁定。当前没有正式签发或电子签章。' : '此笔录已归档，保留原音、文字与历史，只读查看。'}</p></div>}
      <details className="rec-session-meta"><summary><Settings2 size={15}/>询问信息与场景模板 <span>{metaDirty ? '尚未保存' : '查看 / 编辑'}</span></summary><fieldset disabled={locked || Boolean(busy) || captureBusy}><div className="rec-form-grid"><label className="field rec-wide"><span>笔录标题 *</span><input className="input" maxLength={200} value={meta.title} onChange={event => setMeta({ ...meta, title: event.target.value })}/></label><label className="field"><span>业务场景 / 本地模板</span><Choice className="select" value={meta.scenario} onChange={event => setMeta({ ...meta, scenario: event.target.value as RecordScenario })}>{Object.entries(scenarioLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</Choice></label><label className="field"><span>询问地点</span><input className="input" maxLength={500} value={meta.location} onChange={event => setMeta({ ...meta, location: event.target.value })}/></label><label className="field rec-wide"><span>询问人员</span><input className="input" maxLength={500} value={meta.interviewers} onChange={event => setMeta({ ...meta, interviewers: event.target.value })}/></label><label className="field rec-wide"><span>询问发生时间（北京时间，可留空）</span><input className="input" type="datetime-local" value={dateInput(meta.occurred_at)} onChange={event => setMeta({ ...meta, occurred_at: event.target.value ? `${event.target.value}:00+08:00` : null })}/><small className="rec-muted">只登记实际发生时间，未知时保持为空。</small></label></div></fieldset><p className="rec-muted">关联档案在创建时留存快照；场景决定本地整理模板，不自动生成案件结论。</p></details>
      <WorkspacePanels aside={<aside className="rec-sidebar"><section className="panel rec-side-card"><h3>笔录材料</h3><div className="rec-layer-list">{[{ icon: Headphones, title: '原始音频', detail: `${record.audio_clips.length} 段 · 本地原件`, key: 'audio' }, { icon: AudioLines, title: '原始转写', detail: `${record.transcription_attempts.filter(value => value.status === 'succeeded').length} 次成功转写 · 只读`, key: 'original' }, { icon: FilePenLine, title: '人工修订', detail: `${record.segments.length} 段 · v${record.revision}`, key: 'edit' }, { icon: Sparkles, title: '摘要与要素', detail: record.analysis ? record.analysis.stale ? '已过期 · 需重新生成' : '独立保存 · 核对引用' : '尚未生成', key: 'analysis' }].map(layer => <button key={layer.key} onClick={() => setTab(layer.key as StudioTab)}><layer.icon size={17}/><span><strong>{layer.title}</strong><small>{layer.detail}</small></span><ChevronRight size={14}/></button>)}</div></section><section className="panel rec-side-card"><h3><History size={16}/>修订与操作记录</h3><ol className="rec-history">{[...record.history].reverse().slice(0, 12).map(item => <li key={item.id}><i/><div><strong>v{item.revision} · {historyLabel(item.action)}</strong><time>{recordTime(item.created_at)}</time><button className="text-button rec-history-view" disabled={Boolean(busy) || captureBusy} onClick={() => void readRevision(item.revision)}>查看此版<FileText size={11}/></button>{item.note && <p>{item.note}</p>}</div></li>)}</ol>{record.history.length > 12 && <small className="rec-muted">展示最近 12 条，本地历史仍完整保留。</small>}</section></aside>}><Tabs value={tab} onValueChange={value => setTab(value as StudioTab)} asChild><section className="panel rec-main"><TabsList asChild><nav className="rec-tabs" aria-label="笔录工作区">{([{ key: 'audio', label: '原始音频', icon: Headphones }, { key: 'original', label: '原始转写', icon: AudioLines }, { key: 'edit', label: '人工修订', icon: FilePenLine }, { key: 'analysis', label: '摘要与要素', icon: Sparkles }, { key: 'preview', label: '成文预览', icon: FileText }] as const).map(item => <TabsTrigger key={item.key} value={item.key} asChild><button><item.icon size={15}/><span>{item.label}</span>{item.key === 'edit' && segmentsDirty && <i/>}</button></TabsTrigger>)}</nav></TabsList>
        {chosenAudio && <div className="rec-listen-bar"><div><Headphones size={15}/><strong>{chosenAudio.filename}</strong><button className="icon-button" aria-label="关闭回听播放器" onClick={() => setActiveAudio('')}><X size={14}/></button></div><audio ref={audio} key={chosenAudio.id} controls preload="metadata" src={chosenAudio.playback_url} onError={() => setError('当前浏览器无法播放此音频，或本地文件读取失败。可下载原件核实，或使用支持该格式的播放器。')} onLoadedMetadata={() => { if (pendingSeek.current !== null && audio.current) { audio.current.currentTime = pendingSeek.current; pendingSeek.current = null; void audio.current.play().catch(() => setNotice('请点击播放器开始回听。')); } }}/><small>音频内手工位置跳转，不代表逐字时间戳。</small></div>}
        {tab === 'audio' && <TabsContent value="audio" asChild><div className="rec-tab-body"><div className={`rec-capture ${recorder.recording ? 'recording' : ''}`}><div className="rec-capture-top"><span><Mic size={15}/>本地录音台</span><small>约 5 分钟自动停止 · 最大 20 MiB</small></div><div className="rec-capture-center"><div className="rec-mic-orbit"><Mic size={30}/></div><strong>{durationText(recorder.elapsed)}</strong><p>{recorder.recording ? '正在录音 · 原音尚未保存' : recorder.stopping ? '正在完成录音文件…' : '主动开始录音后才会申请麦克风权限'}</p></div><div className="rec-record-controls">{recorder.recording ? <Access permission="write"><button className="btn rec-stop" onClick={recorder.stop} disabled={recorder.stopping}><Square size={15} fill="currentColor"/>停止录音</button></Access> : <Access permission="write"><button className="btn btn-primary" onClick={() => void recorder.start()} disabled={!canMutate || Boolean(pendingLocal) || record.audio_clips.length >= maxClips || totalAudioBytes >= maxTotalAudio}>{recorder.starting ? <LoaderCircle className="spinning" size={16}/> : <Mic size={16}/>}开始录音</button></Access>}<Access permission="write"><button className="btn btn-secondary" onClick={() => fileInput.current?.click()} disabled={!canMutate || Boolean(pendingLocal) || record.audio_clips.length >= maxClips || totalAudioBytes >= maxTotalAudio}><Upload size={15}/>上传音频</button></Access><>{audioLibraryAvailable && <Access permission="write"><button className="btn btn-secondary" disabled={!readyForAction} onClick={() => void addLibraryAudio()}><Headphones size={15}/>从录音资料库添加</button></Access>}</><input className="rec-hidden" type="file" ref={fileInput} accept=".wav,.mp3,.webm,.ogg,.m4a,.flac" onChange={event => { chooseFile(event.target.files?.[0]); event.target.value = ''; }} disabled={!write} aria-label="上传本地询问音频"/></div><p className="rec-capture-note">计时为浏览器估计。请保持页面前台；锁屏或后台可能延迟停止，保存前请试听。无实时转写或自动说话人识别。</p></div><Notice error={recorder.error} message={recorder.notice}/>
          {localBlob && localURL && <section className="rec-pending-audio"><header><span><Clock3 size={16}/>尚未保存的本地音频</span><strong>{bytesText(localBlob.size)}</strong></header><p>{localName}{recorder.local ? ` · 浏览器估计 ${durationText(recorder.local.duration)}` : ''}</p><audio controls preload="metadata" src={localURL} onError={() => setError('当前浏览器暂无法试听此格式。本地音频仍保留，可先下载核实；请勿丢弃未确认的录音。')}/>{file && <label className="field"><span>声明时长（秒，可留空）</span><input className="input" type="number" min={0.001} max={86400} step={0.001} value={fileDuration} disabled={Boolean(busy)} onChange={event => setFileDuration(event.target.value)} placeholder="未知时长留空，系统不伪造测量结果"/></label>}<div><Access permission="write"><a className="btn btn-secondary" href={localURL} download={localName}><ArrowDownToLine size={14}/>下载保留</a></Access><Access permission="write"><button className="btn btn-secondary" onClick={discardLocal} disabled={Boolean(busy)}>丢弃</button></Access><Access permission="write"><button className="btn btn-primary" onClick={upload} disabled={!canMutate || textDirty || localBlob.size > maxAudio || localBlob.size + totalAudioBytes > maxTotalAudio}><Check size={15}/>保存到本地</button></Access></div><small>上传失败仍保留此音频。{textDirty ? '请先保存上方资料或修订文字，再保存音频。' : '保存成功后可另录下一段。'}</small></section>}
          <div className="rec-section-heading"><h3>已保存原音 <span>{record.audio_clips.length}</span></h3><small>最多 {maxClips} 段 / 500 MiB · 原件保留</small></div>{!record.audio_clips.length ? <Empty icon={<Headphones size={30}/>} title="这里将保留每一段原音">开始录音或上传已有音频。原始文件保存在当前环境数据库。</Empty> : <div className="rec-audio-list">{record.audio_clips.map((clip, index) => <article className="rec-audio-card" key={clip.id}><span className="rec-audio-number">{String(index + 1).padStart(2, '0')}</span><div><h4>{clip.filename}</h4><p>{clip.format.toUpperCase()} · {bytesText(clip.size_bytes)} · {clip.duration_ms ? `声明时长 ${durationText(clip.duration_ms / 1000)}` : '时长未登记'}</p><small>{recordTime(clip.created_at)} · SHA256 {clip.sha256.slice(0, 12)}…</small><div className="rec-audio-actions"><button onClick={() => playAudio(clip.id)}><Play size={13}/>播放</button><Access permission="write"><a href={`${clip.playback_url}?download=true`} download><ArrowDownToLine size={13}/>原件</a></Access>{!locked && <Access permission="write"><button disabled={!readyForAction || !capabilities?.ai.asr.ready || (clip.format !== 'mp3' && !capabilities?.local_conversion_available)} onClick={() => openDialog({ type: 'asr', clip })}><AudioLines size={13}/>转写所选音频</button></Access>}</div>{clip.format !== 'mp3' && !capabilities?.local_conversion_available && <p className="rec-warning">本机未检测到 FFmpeg，此格式暂不能转写。请由维护人员安装本地转换工具，或另上传 MP3；原音保存和回听不受影响。</p>}</div></article>)}</div>}
          {!locked && !capabilities?.ai.asr.ready && <div className="rec-config"><Settings2 size={17}/><p>录音与上传可本地使用。转写需在后台启用硅基流动和可用的语音模型。</p><Access permission="admin"><button onClick={() => onNavigate('settings')}>前往配置<ArrowRight size={13}/></button></Access><button className="icon-button" aria-label="重新检查AI配置" onClick={onReloadCapabilities}><RotateIcon/></button></div>}
        </div></TabsContent>}
        {tab === 'original' && <TabsContent value="original" asChild><div className="rec-tab-body"><div className="rec-pane-title"><div><span>IMMUTABLE SOURCE</span><h3>转写原文，独立留存。</h3></div><LockKeyhole size={22}/></div><p className="rec-muted">每次转写仅发送所选音频至硅基流动。原文只读，不标注未经模型返回的逐字时间或说话人。重复转写会追加新段，不覆盖修订。</p>{record.transcription_attempts.length ? [...record.transcription_attempts].sort((a, b) => b.created_at.localeCompare(a.created_at)).map(attempt => <article className="rec-transcript" key={attempt.id}><header><strong>{record.audio_clips.find(clip => clip.id === attempt.audio_id)?.filename || '原始音频'}</strong><span className={`rec-attempt ${attempt.status}`}>{({ processing: '处理中', succeeded: '已保存', failed: '失败', stale: '版本已变化' })[attempt.status]}</span></header><small>{providerName(attempt.provider)} · {attempt.model} · {recordTime(attempt.created_at)}</small>{attempt.text && <p className="rec-verbatim">{attempt.text}</p>}{attempt.error && <Notice error={attempt.error}/>}</article>) : <Empty icon={<AudioLines size={30}/>} title="还没有原始转写">在原始音频中选择一段并确认转写，也可以直接在人工修订中手工录入。</Empty>}</div></TabsContent>}
        {tab === 'edit' && <TabsContent value="edit" asChild><div className="rec-tab-body"><div className="rec-section-heading"><div><h3>人工核对工作区 <span>{segments.length} 段</span></h3><p>校对文字、标注角色，必要时手工填写音频内位置。</p></div>{!locked && <Access permission="write"><button className="btn btn-secondary" disabled={Boolean(busy) || captureBusy || segments.length >= (capabilities?.limits.max_segments || 500)} onClick={() => setSegments(items => [...items, { key: `new-${++segmentCounter.current}`, audio_id: null, start_ms: null, end_ms: null, speaker: 'unknown', text: '' }])}><Plus size={14}/>手工段</button></Access>}</div><div className="rec-boundary"><ShieldCheck size={15}/><p>角色和时间位置由人工填写；原始转写始终保留。正文不得用 AI 摘要代替逐字核对。</p></div>{segments.length ? <div className="rec-segment-list">{segments.map((segment, index) => <article className="rec-segment" key={segment.key} id={`rec-segment-${segment.id || segment.key}`}><header><strong><span>{String(index + 1).padStart(2, '0')}</span>{record.segments.find(value => value.id === segment.id)?.source === 'asr' ? '由原始转写建立' : '人工录入段'}</strong><div>{segment.audio_id && <button type="button" onClick={() => listen(segment)}><Headphones size={13}/>回听</button>}{!locked && <Access permission="write"><button aria-label={`移除第${index + 1}段`} disabled={Boolean(busy) || captureBusy} onClick={async () => { if ((await confirmAction('从当前修订稿移除此段？已保存的原始转写和历史不会删除。', {"title":"移除当前文字片段？","confirmLabel":"移除此段","tone":"danger"}))) setSegments(items => items.filter(value => value.key !== segment.key)); }}><X size={15}/></button></Access>}</div></header><div className="rec-segment-fields"><label><span>角色（人工标注）</span><Choice className="select" value={segment.speaker} disabled={locked || Boolean(busy) || captureBusy} onChange={event => changeSegment(segment.key, { speaker: event.target.value as Speaker })}>{Object.entries(speakerLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Choice></label><label><span>关联音频</span><Choice className="select" value={segment.audio_id || ''} disabled={locked || Boolean(busy) || captureBusy} onChange={event => changeSegment(segment.key, { audio_id: event.target.value || null, start_ms: null, end_ms: null })}><option value="">未关联</option>{record.audio_clips.map((clip, i) => <option key={clip.id} value={clip.id}>{i + 1}. {clip.filename}</option>)}</Choice></label><label><span>开始（秒）</span><input className="input" type="number" min={0} step={0.001} value={segment.start_ms === null ? '' : segment.start_ms / 1000} disabled={locked || Boolean(busy) || captureBusy || !segment.audio_id} onChange={event => changeSegment(segment.key, { start_ms: event.target.value === '' ? null : Math.round(Number(event.target.value) * 1000) })}/></label><label><span>结束（秒）</span><input className="input" type="number" min={0} step={0.001} value={segment.end_ms === null ? '' : segment.end_ms / 1000} disabled={locked || Boolean(busy) || captureBusy || !segment.audio_id} onChange={event => changeSegment(segment.key, { end_ms: event.target.value === '' ? null : Math.round(Number(event.target.value) * 1000) })}/></label></div><textarea className="input rec-segment-text" aria-label={`第${index + 1}段修订文字`} rows={5} maxLength={capabilities?.limits.max_segment_chars || 20000} value={segment.text} disabled={locked || Boolean(busy) || captureBusy} onChange={event => changeSegment(segment.key, { text: event.target.value })} placeholder="忠实记录并校对原话；不确定的词语请标记待核实"/><footer><span>{segment.start_ms === null ? '未标注音频时间' : '时间位置为人工填写'}</span><span>{segment.text.length} 字</span></footer></article>)}</div> : <Empty icon={<FilePenLine size={29}/>} title="等待第一段文字">完成音频转写后会自动追加一段，也可以点击“手工段”开始录入。</Empty>}<div className="rec-edit-footer"><span>{totalChars.toLocaleString()} / {(capabilities?.limits.max_total_text_chars || 100000).toLocaleString()} 字</span>{!locked && <Access permission="write"><button className="btn btn-primary" disabled={!textDirty || !canMutate} onClick={saveChanges}><Check size={15}/>保存修订与历史</button></Access>}</div></div></TabsContent>}
        {tab === 'analysis' && <TabsContent value="analysis" asChild><div className="rec-tab-body"><div className="rec-pane-title"><div><span>ANALYSIS, WITH REFERENCES</span><h3>摘要不是原话。</h3></div><Sparkles size={24}/></div><p className="rec-muted">仅分析已保存的人工修订文字。摘要、要素及待核实项单独呈现，不改写笔录原文。</p><div className="rec-analysis-control"><div><strong>{capabilities?.ai.analysis.ready ? `${providerName(capabilities.ai.analysis.provider)} · ${capabilities.ai.analysis.model}` : '摘要服务尚未就绪'}</strong><small>每次最多分析 {(capabilities?.limits.max_analyze_chars || 30000).toLocaleString()} 字；超出时需精简分段内容。</small></div>{!locked && (capabilities?.ai.analysis.ready ? <Access permission="write"><button className="btn btn-primary" disabled={!readyForAction || !segments.some(segment => segment.text.trim()) || totalChars > (capabilities?.limits.max_analyze_chars || 30000)} onClick={() => openDialog({ type: 'analysis' })}><Sparkles size={15}/>整理摘要与要素</button></Access> : <Access permission="admin"><button className="btn btn-secondary" onClick={() => onNavigate('settings')}><Settings2 size={15}/>配置 AI</button></Access>)}</div>{textDirty && <p className="rec-warning">请先保存修订，再分析这份文字。</p>}
          {record.analysis ? <>{record.analysis.provider === 'local' && <p className="rec-warning">这是此前保存的文字整理资料，未经过在线模型处理。请使用“生成摘要与要素”重新分析当前正文。</p>}<div className={`rec-analysis-state ${record.analysis.stale ? 'stale' : ''}`}><span>{record.analysis.stale ? <CircleAlert size={16}/> : <CheckCircle2 size={16}/>} {record.analysis.stale ? '修订稿已变化 · 此摘要已过期' : segmentsDirty ? '存在未保存修订 · 引用查看分析输入快照' : '对应当前已保存文字'}</span><small>{recordTime(record.analysis.created_at)}</small></div>{record.analysis.stale && <p className="rec-warning">以下仅供查看历史，不可附入当前导出。请保存最新文字后重新生成。</p>}<section className="rec-summary"><h4>内容摘要</h4><p>{record.analysis.summary}</p></section><section className="rec-facts"><h4>结构化要素 <span>{record.analysis.key_facts.length}</span></h4>{record.analysis.key_facts.map((fact, index) => <article key={index}><strong>{fact.label}</strong><p>{fact.value}</p><div>{fact.segment_ids.map(segmentId => { const source = record.analysis!.input_segments.find(segment => segment.segment_id === segmentId); const currentExists = record.segments.some(segment => segment.id === segmentId); return <button key={segmentId} onClick={() => { if (record.analysis!.stale || segmentsDirty || !currentExists) setSnapshot({ title: `${fact.label} · 分析时的文字快照`, text: source?.text || '未找到对应的分析快照。' }); else navigateToSegment(segmentId); }}><FileText size={12}/>{record.analysis!.stale || segmentsDirty || !currentExists ? '查看输入快照' : `依据 ${record.segments.findIndex(segment => segment.id === segmentId) + 1}`}</button>; })}</div></article>)}</section>{record.analysis.issues.length > 0 && <section className="rec-issues"><h4><CircleAlert size={16}/>待核实事项</h4><ul>{record.analysis.issues.map((issue, index) => <li key={index}>{issue}</li>)}</ul></section>}</> : <Empty icon={<Sparkles size={30}/>} title="让整理与原文保持距离">生成摘要前需要明确确认外发范围，结果保留对应原文引用。</Empty>}
          {!!record.analyses.length && <details className="rec-analysis-history"><summary><History size={15}/>分析请求记录 · {record.analyses.length}</summary>{[...record.analyses].sort((a, b) => b.created_at.localeCompare(a.created_at)).map(value => <article key={value.id}><span>{recordTime(value.created_at)} · {providerName(value.provider)} · {({ processing: '处理中', succeeded: value.stale ? '已过期' : '成功', failed: '失败', stale: '版本冲突' })[value.status]}</span>{value.error && <p>{value.error}</p>}</article>)}</details>}
        </div></TabsContent>}
        {tab === 'preview' && <TabsContent value="preview" asChild><div className="rec-tab-body"><div className="rec-section-heading"><div><h3>{capabilities?.templates.find(template => template.id === record.template_id)?.name || scenarioLabels[record.scenario]}</h3><p>本地场景模板 · {textDirty ? '当前为上次保存的版本' : '当前已保存版本'}</p></div><span className={`rec-status ${record.status}`}>{recordStatusLabels[record.status]}</span></div><div className="rec-paper"><div className="rec-paper-label">{record.status === 'reviewed' ? '人工核对稿 · 未签发' : '草稿 · 待人工审核'}</div><pre>{record.rendered_text}</pre></div><label className="rec-ai-export"><input type="checkbox" checked={includeAI} disabled={!record.analysis || record.analysis.stale || Boolean(busy)} onChange={event => setIncludeAI(event.target.checked)}/><span>导出时另附非过期 AI 摘要与要素（明确标为辅助内容）</span></label><div className="rec-export-actions"><Access permission="write"><button className="btn btn-secondary" disabled={Boolean(busy) || textDirty || Boolean(pendingLocal) || captureBusy || record.status === 'archived'} onClick={() => void download('txt')}><ArrowDownToLine size={15}/>导出 TXT</button></Access><Access permission="write"><button className="btn btn-secondary" disabled={Boolean(busy) || textDirty || Boolean(pendingLocal) || captureBusy || record.status === 'archived'} onClick={() => void download('docx')}><FileText size={15}/>导出 Word</button></Access>{record.status === 'draft' && <Access permission="write"><button className="btn btn-primary" disabled={!readyForAction || !record.segments.some(segment => segment.text.trim())} onClick={() => openDialog({ type: 'review' })}><ShieldCheck size={15}/>全文核对并锁定</button></Access>}</div><p className="rec-muted">导出保留草稿或未签发标识。系统不执行签名、盖章或送达；人工核对后正文锁定。</p></div></TabsContent>}
      </section></Tabs></WorkspacePanels>
      {textDirty && <div className="rec-unsaved-strip"><span><CircleAlert size={15}/>修改尚未保存</span><Access permission="write"><button className="btn btn-primary" onClick={saveChanges} disabled={!canMutate}><Check size={14}/>保存修改</button></Access></div>}
    </>}
    {dialog && !snapshot && <Dialog title={dialog.type === 'asr' ? '确认音频外发转写' : dialog.type === 'analysis' ? '确认修订文字外发分析' : '全文人工核对'} onClose={closeDialog} className="rec-confirm-dialog"><div className="rec-dialog-lead"><span>{dialog.type === 'review' ? <ShieldCheck size={24}/> : <LockKeyhole size={24}/>}</span><div><h3>{dialog.type === 'review' ? '核对全文，再锁定版本。' : '本次发送范围清晰可见。'}</h3><p>{dialog.type === 'review' ? '核对状态不等于正式签发或法律效力认定。' : '这是一次主动云端处理，相关内容将离开本地环境。'}</p></div></div>{dialog.type === 'review' ? <><label className="field"><span>人工核对意见 *</span><textarea className="input" rows={4} maxLength={4000} value={reviewNote} onChange={event => setReviewNote(event.target.value)} disabled={Boolean(busy)} placeholder="记录原音、修订全文、角色及时间位置的核对情况"/></label><label className="rec-consent"><input type="checkbox" checked={confirmed} disabled={Boolean(busy)} onChange={event => setConfirmed(event.target.checked)}/><span>我已核对全文和原音，确认修订内容与本次询问一致；摘要未作为逐字原话替代。核对后锁定正文。</span></label></> : <><dl className="rec-send-scope"><div><dt>服务商</dt><dd>{dialog.type === 'asr' ? '硅基流动' : providerName(capabilities?.ai.analysis.provider)}</dd></div><div><dt>模型</dt><dd>{dialog.type === 'asr' ? capabilities?.ai.asr.model : capabilities?.ai.analysis.model}</dd></div><div><dt>本次发送</dt><dd>{dialog.type === 'asr' ? `${dialog.clip.filename} · 原件 ${bytesText(dialog.clip.size_bytes)}，仅发送此段音频（非 MP3 先本地转换）` : `已保存修订文字，共 ${totalChars.toLocaleString()} 字；整理摘要与要素`}</dd></div></dl><p className="rec-muted">{dialog.type === 'asr' ? 'MP3直接发送；其他格式通过本机FFmpeg转换为MP3后发送，不调用外部转换服务，原音保持不变。不发送其他音频，不承诺逐字时间戳或自动角色识别，成功后追加新段。' : '不发送原始音频或自动读取人员档案。文字本身可能含有个人资料，请确认已具备本次外发授权。'}</p><label className="rec-consent"><input type="checkbox" checked={confirmed} disabled={Boolean(busy)} onChange={event => setConfirmed(event.target.checked)}/><span>确认允许将上述内容发送至指定服务商完成本次处理。</span></label></>}<Notice error={error}/><div className="rec-form-footer"><button className="btn btn-secondary" disabled={Boolean(busy)} onClick={closeDialog}>取消</button><Access permission="write"><button className="btn btn-primary" disabled={Boolean(busy) || !confirmed || dialog.type === 'review' && !reviewNote.trim()} onClick={() => dialog.type === 'review' ? void changeStatus('reviewed') : void runAI()}>{busy ? <LoaderCircle className="spinning" size={16}/> : <Check size={16}/>} {dialog.type === 'review' ? '确认核对并锁定' : '确认并开始'}</button></Access></div></Dialog>}
    {snapshot && <Dialog title={snapshot.title} onClose={() => setSnapshot(null)} className="rec-snapshot-dialog"><p className="rec-muted">{snapshot.note || '这是分析发生时的输入快照，不代表当前修订版本。'}</p><p className="rec-verbatim">{snapshot.text}</p></Dialog>}
  </div>;
}

function RotateIcon() { return <History size={14}/>; }
function historyLabel(action: string) { return ({ created: '创建笔录', updated: '更新资料', segments_updated: '保存人工修订', audio_uploaded: '保存原始音频', audio_added: '保存原始音频', restored: '恢复归档', transcribed: '保存转写', analyzed: '保存分析', reviewed: '人工核对', archived: '归档', transcript_saved: '保存转写', analysis_saved: '保存分析' } as Record<string, string>)[action] || action; }

export function Records({ onNavigate }: { onNavigate: (page: PageId) => void }) {
  const [data, setData] = useState<RecordList | null>(null), [capabilities, setCapabilities] = useState<RecordCapabilities | null>(null);
  const [query, setQuery] = useViewState('records.query', ''), [search, setSearch] = useViewState('records.search', ''), [status, setStatus] = useViewState<'all' | RecordStatus>('records.status', 'all'), [page, setPage] = useViewState('records.page', 1);
  const [loading, setLoading] = useState(true), [error, setError] = useState(''), [capError, setCapError] = useState(''), [creating, setCreating] = useState(false), [selected, setSelected] = useState<string | null>(null), [reload, setReload] = useState(0);
  const loadCapabilities = useCallback(async () => { setCapError(''); try { const value = await api<RecordCapabilities>('/records/capabilities'); if (!value?.limits || !value.ai || !Array.isArray(value.templates)) throw new Error('笔录能力配置响应不完整。'); setCapabilities(value); } catch (error) { setCapabilities(null); setCapError(recordError(error)); } }, []);
  useEffect(() => { void loadCapabilities(); }, [loadCapabilities]);
  useEffect(() => { if (query.trim() === search) return; const timer = window.setTimeout(() => { setSearch(query.trim()); setPage(1); }, 300); return () => window.clearTimeout(timer); }, [query, search, setSearch, setPage]);
  useEffect(() => { let cancelled = false; setLoading(true); setError(''); api<RecordList>(`/records?${new URLSearchParams({ q: search, status, page: String(page), page_size: '12' })}`).then(value => { if (!value || !Array.isArray(value.items) || !value.stats) throw new Error('笔录列表响应不完整。'); if (cancelled) return; const last = Math.max(1, Math.ceil(value.total / 12)); if (page > last) { setPage(last); return; } setData(value); }).catch(error => { if (!cancelled) { setError(recordError(error)); setData(null); } }).finally(() => { if (!cancelled) setLoading(false); }); return () => { cancelled = true; }; }, [search, status, page, reload]);
  const refresh = () => setReload(value => value + 1);
  const listView = useListPosition(`records:${JSON.stringify([search,status,page])}`, !selected && !creating, !loading);
  const openRecord = (id:string) => { listView.remember(id); setSelected(id); };
  if (selected) return <Studio key={selected} id={selected} capabilities={capabilities} onBack={() => { setSelected(null); refresh(); }} onChanged={refresh} onNavigate={onNavigate} onReloadCapabilities={loadCapabilities}/>;
  return <div className="page-content records-page"><PageHeading title="询问笔录" description="录音、转写、校对与成文；原始音频随笔录留存。" scene="records"><Access permission="write"><button className="btn btn-primary" onClick={() => setCreating(true)}><Plus size={17}/>新建笔录</button></Access></PageHeading>
    <section className="rec-stats" aria-label="笔录库统计">{[{ label: '全部笔录', value: data?.stats.total, icon: Layers3 }, { label: '整理中', value: data?.stats.draft, icon: FilePenLine }, { label: '已人工核对', value: data?.stats.reviewed, icon: ShieldCheck }, { label: '已归档', value: data?.stats.archived, icon: Archive }].map(stat => <div key={stat.label}><stat.icon size={20}/><span><small>{stat.label}</small><strong>{stat.value ?? '—'}<i>份</i></strong></span></div>)}</section>
    {capError && <div className="rec-cap-error"><Notice error={capError}/><button className="text-button" onClick={loadCapabilities}>重新读取能力配置</button></div>}<section className="panel rec-library"><header><div><h2>笔录档案</h2></div><span className="rec-local"><LockKeyhole size={12}/>当前环境 · 本地保存</span></header><div className="rec-library-tools"><div className="rec-status-tabs" role="group" aria-label="筛选笔录状态">{([{ value: 'all', label: '全部' }, ...Object.entries(recordStatusLabels).map(([value, label]) => ({ value: value as RecordStatus, label }))] as const).map(item => <button key={item.value} aria-pressed={status === item.value} onClick={() => { setStatus(item.value); setPage(1); }}>{item.label}</button>)}</div><label className="rec-search"><Search size={15}/><input maxLength={200} value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索笔录标题…" aria-label="搜索笔录标题"/></label></div>{error ? <div className="rec-library-error"><Notice error={error}/><button className="btn btn-secondary" onClick={refresh}>重试读取</button></div> : loading && !data ? <Empty icon={<LoaderCircle size={27} className="spinning"/>} title="正在读取笔录库">从当前本地数据库读取记录。</Empty> : data?.items.length ? <div className="rec-record-grid" aria-busy={loading}>{data.items.map(record => <button className="rec-record-card" key={record.id} data-work-row={record.id} data-selected={listView.selectedRow===record.id} onClick={() => openRecord(record.id)}><div><span className="rec-scenario">{scenarioLabels[record.scenario]}</span><span className={`rec-status ${record.status}`}>{recordStatusLabels[record.status]}</span></div><h3>{record.title}</h3><p>{record.person_name || '未关联人员档案'}{record.person_code && <span className="work-id"> · {record.person_code}</span>}{record.location ? ` · ${record.location}` : ''}</p><div className="rec-card-counts"><span>{record.audio_count} 段音频{record.audio_count > 0 && <> · {record.audio_duration_ms != null ? `${record.audio_unknown_duration_count ? '已知 ' : ''}${formatDuration(record.audio_duration_ms)}` : '时长未记录'}{record.audio_unknown_duration_count > 0 && record.audio_duration_ms != null && `（另 ${record.audio_unknown_duration_count} 段时长未知）`}</>}</span><span>{record.segment_count} 段文字</span></div><p className="work-next-step">{record.status==='archived'?'已归档，可查看原音与留存正文':record.status==='reviewed'?'已人工核对，可预览与导出':record.segment_count?'待校对文字、说话人与原音关联':record.audio_count?'已保留原音，待转写或手工录入':'待录音、上传音频或录入文字'}</p><footer><span>{recordTime(record.updated_at)}</span><span>{record.status==='draft'?'继续整理':'查看笔录'}<ArrowRight size={13}/></span></footer></button>)}</div> : <Empty icon={<Mic size={34}/>} title={search || status !== 'all' ? '没有符合条件的笔录' : '暂无笔录'}>{search || status !== 'all' ? '调整搜索词或状态筛选后重试。' : '新建笔录后，可以录音、上传音频或手工录入。音频与校对记录分别保存。'}</Empty>}<footer className="rec-pagination"><span>{data ? `共 ${data.total} 份笔录` : '等待数据连接'}</span><div><button className="icon-button" aria-label="上一页" disabled={loading || page <= 1} onClick={() => setPage(value => value - 1)}><ChevronLeft size={16}/></button><span>{page} / {Math.max(1, Math.ceil((data?.total || 0) / 12))}</span><button className="icon-button" aria-label="下一页" disabled={loading || page * 12 >= (data?.total || 0)} onClick={() => setPage(value => value + 1)}><ChevronRight size={16}/></button></div></footer></section>{creating && <CreateRecord onClose={() => setCreating(false)} onCreated={id => { setCreating(false); openRecord(id); refresh(); }}/>}</div>;
}

export default Records;
